require_once __DIR__.'/../includes/bootstrap.php';$user=require_login();$workspace=require_workspace();$message='';$error='';$action=(string)($_POST['action']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!can('manage_members',$workspace)){http_response_code(403);exit('Peran workspace Anda tidak dapat mengelola anggota.');}if($action==='rename'){$name=trim((string)($_POST['name']??''));if(mb_strlen($name,'UTF-8')<2||mb_strlen($name,'UTF-8')>140)$error='Nama workspace harus 2–140 karakter.';else{$GLOBALS['pdo']->prepare('UPDATE workspaces SET name=? WHERE id=?')->execute([$name,$workspace['id']]);audit_log('workspace.renamed','workspace',(int)$workspace['id']);$message='Nama workspace diperbarui.';$workspace=current_workspace();}}elseif($action==='add-member'){$email=strtolower(trim((string)($_POST['email']??'')));$role=(string)($_POST['member_role']??'viewer');if($workspace['plan']!=='business')$error='Manajemen anggota tersedia pada Business.';elseif(!in_array($role,['admin','editor','analyst','viewer'],true))$error='Peran anggota tidak valid.';else{$st=$GLOBALS['pdo']->prepare('SELECT id FROM users WHERE email=? AND is_active=1 LIMIT 1');$st->execute([$email]);$target=(int)$st->fetchColumn();if(!$target)$error='Email harus milik akun Datanix aktif yang sudah dibuat; prototype ini tidak mengirim undangan email.';else{$st=$GLOBALS['pdo']->prepare('SELECT COUNT(*) FROM workspace_members WHERE workspace_id=?');$st->execute([$workspace['id']]);$limit=plan_limits($workspace)['members'];if($limit!==-1&&(int)$st->fetchColumn()>=$limit)$error='Batas anggota paket telah tercapai.';else{try{$GLOBALS['pdo']->prepare('INSERT INTO workspace_members(workspace_id,user_id,member_role,invited_by) VALUES(?,?,?,?)')->execute([$workspace['id'],$target,$role,$user['id']]);audit_log('workspace.member_added','user',$target,['role'=>$role]);$message='Anggota ditambahkan ke workspace.';}catch(PDOException $e){$error=$e->getCode()==='23000'?'Anggota tersebut sudah terdaftar.':'Anggota belum dapat ditambahkan.';}}}}}elseif($action==='member-role'||$action==='remove-member'){$target=(int)($_POST['user_id']??0);$st=$GLOBALS['pdo']->prepare('SELECT member_role FROM workspace_members WHERE workspace_id=? AND user_id=?');$st->execute([$workspace['id'],$target]);$targetRole=$st->fetchColumn();if(!$targetRole)$error='Anggota tidak ditemukan.';elseif($target===(int)$user['id']||$targetRole==='owner')$error='Pemilik tidak dapat dikeluarkan atau mengubah perannya sendiri.';elseif($action==='remove-member'){$GLOBALS['pdo']->prepare('DELETE FROM workspace_members WHERE workspace_id=? AND user_id=?')->execute([$workspace['id'],$target]);audit_log('workspace.member_removed','user',$target);$message='Anggota dihapus.';}else{$role=(string)($_POST['member_role']??'viewer');if(!in_array($role,['admin','editor','analyst','viewer'],true))$error='Peran tidak valid.';elseif($workspace['plan']!=='business')$error='Peran tim tersedia pada Business.';else{$GLOBALS['pdo']->prepare('UPDATE workspace_members SET member_role=? WHERE workspace_id=? AND user_id=?')->execute([$role,$workspace['id'],$target]);audit_log('workspace.member_role_changed','user',$target,['role'=>$role]);$message='Peran anggota diperbarui.';}}}else{$error='Tindakan tidak dikenal.';}}
$st=$GLOBALS['pdo']->prepare('SELECT u.id,u.name,u.email,m.member_role,m.created_at FROM workspace_members m JOIN users u ON u.id=m.user_id WHERE m.workspace_id=? ORDER BY FIELD(m.member_role,"owner","admin","editor","analyst","viewer"),u.name');$st->execute([$workspace['id']]);$members=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='app';datanix_header('Workspace settings','settings',$layout);
?>
<div class="page-head"><div><div class="section-kicker">SETTINGS</div><h1>Workspace settings</h1><p>Nama, paket, peran anggota dan tingkat akses untuk <?=e($workspace['name'])?>.</p></div></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-3"><div class="col-lg-5"><section class="panel"><div class="panel-head"><h2 class="panel-title">Informasi workspace</h2><span class="badge-plan"><?=e(strtoupper($workspace['plan']))?></span></div><div class="panel-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="rename"><label class="form-label">Nama workspace</label><input class="form-control mb-3" name="name" value="<?=e($workspace['name'])?>" maxlength="140" required><label class="form-label">Slug</label><input class="form-control mb-3" value="<?=e($workspace['slug'])?>" readonly><div class="small-muted">Role Anda: <strong><?=e($workspace['member_role'])?></strong></div><button class="btn btn-primary btn-sm mt-3" <?=can('manage_members',$workspace)?'':'disabled'?>>Simpan nama</button></form></div></section><section class="panel mt-3"><div class="panel-head"><h2 class="panel-title">Paket & pemakaian</h2></div><div class="panel-body"><p class="small-muted"><?=e(strtoupper($workspace['plan']))?> · <?=e(usage_count('ai_query',(int)$workspace['id']))?> pertanyaan AI bulan ini dari <?=e(plan_limits($workspace)['queries'])?>.</p><a href="<?=e(url('plans.php'))?>" class="btn btn-light-outline btn-sm">Lihat opsi paket</a></div></section></div><div class="col-lg-7"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Anggota tim</h2><div class="panel-subtitle">Hanya akun aktif yang sudah mendaftar. Tidak ada email undangan otomatis.</div></div><span class="badge-soft"><?=count($members)?> anggota</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nama</th><th>Peran</th><th></th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><strong><?=e($m['name'])?></strong><br><small class="text-subtle"><?=e($m['email'])?></small></td><td><?php if($m['member_role']==='owner'):?><span class="badge-soft brand">Owner</span><?php elseif($workspace['plan']==='business'&&can('manage_members',$workspace)&&$m['id']!==$user['id']):?><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="action" value="member-role"><input type="hidden" name="user_id" value="<?=e($m['id'])?>"><select name="member_role" class="form-select form-select-sm"><?php foreach(['admin','editor','analyst','viewer'] as $role):?><option value="<?=$role?>" <?=$m['member_role']===$role?'selected':''?>><?=ucfirst($role)?></option><?php endforeach;?></select><button class="btn btn-light-outline btn-sm">Simpan</button></form><?php else:?><span class="badge-soft"><?=e(ucfirst($m['member_role']))?></span><?php endif;?></td><td><?php if($m['member_role']!=='owner'&&$m['id']!==$user['id']&&can('manage_members',$workspace)):?><form method="post" data-confirm="Keluarkan anggota ini dari workspace?"><?=csrf_field()?><input type="hidden" name="action" value="remove-member"><input type="hidden" name="user_id" value="<?=e($m['id'])?>"><button class="btn btn-sm btn-light-outline">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php if($workspace['plan']==='business'&&can('manage_members',$workspace)):?><section class="panel mt-3"><div class="panel-head"><h2 class="panel-title">Tambahkan anggota</h2></div><div class="panel-body"><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="add-member"><div class="col-md-6"><label class="form-label">Email akun</label><input class="form-control" type="email" name="email" required></div><div class="col-md-4"><label class="form-label">Peran</label><select class="form-select" name="member_role"><option>viewer</option><option>analyst</option><option>editor</option><option>admin</option></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Tambah</button></div></form><p class="small-muted mt-2">Peran memisahkan baca, tanya, edit data, integrasi dan administrasi anggota. Upgrade request akan direview admin platform secara manual.</p></div></section><?php else:?><section class="panel mt-3"><div class="panel-body"><strong>Team workspace</strong><p class="small-muted mt-2">Manajemen anggota tersedia di Business. Ajukan akses tanpa pembayaran otomatis.</p><a class="btn btn-light-outline btn-sm" href="<?=e(url('plans.php'))?>">Minta akses Business</a></div></section><?php endif;?></div></div>
